const crypto = require('crypto');

const allowedEvents = new Set([
  'service_request.created',
  'service_request.updated',
  'technician_application.created',
  'technician_application.updated',
]);

const getHeader = (headers, name) => {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(headers || {})) {
    if (key.toLowerCase() === target) return Array.isArray(value) ? value[0] : String(value);
  }
  return '';
};

const hmac = (body, secret) => crypto.createHmac('sha256', secret).update(body).digest('hex');

const timingSafeEqual = (a, b) => {
  const left = Buffer.from(a || '', 'utf8');
  const right = Buffer.from(b || '', 'utf8');
  return left.length === right.length && crypto.timingSafeEqual(left, right);
};

const normalizeThaiPhone = (value) => {
  const digits = String(value || '').replace(/\D/g, '');
  if (!digits) return '';
  if (digits.startsWith('66')) return digits;
  if (digits.startsWith('0')) return `66${digits.slice(1)}`;
  if (digits.length === 9) return `66${digits}`;
  return digits;
};

const compact = (value, fallback = 'Not provided') => {
  const text = String(value || '').trim();
  return text || fallback;
};

const body = $json.body && typeof $json.body === 'object' ? $json.body : {};
const rawBody = JSON.stringify(body);
const headers = $json.headers || {};
const incomingSecret = process.env.ONEHANDY_N8N_WEBHOOK_SECRET || process.env.N8N_WEBHOOK_SECRET || '';
const signatureHeader = getHeader(headers, 'X-OneHandy-Signature');
const expectedSignature = incomingSecret ? `sha256=${hmac(rawBody, incomingSecret)}` : '';

if (!incomingSecret || !signatureHeader || !timingSafeEqual(signatureHeader, expectedSignature)) {
  return [{
    json: {
      statusCode: 401,
      responseBody: {
        ok: false,
        error: 'Invalid OneHandy webhook signature',
        receivedAt: new Date().toISOString(),
      },
    },
  }];
}

const eventType = body.eventType || getHeader(headers, 'X-OneHandy-Event') || 'unknown';
const objectId = body.objectId || body.data?.id || 'unknown';
const objectType = body.objectType || 'unknown';

if (!allowedEvents.has(eventType)) {
  return [{
    json: {
      statusCode: 202,
      responseBody: {
        ok: true,
        ignored: true,
        eventType,
        objectId,
        receivedAt: new Date().toISOString(),
      },
    },
  }];
}

let hermesStatus = null;
let hermesBody = null;
let hermesDelivered = false;

if (eventType === 'service_request.created') {
  const siteUrl = (process.env.ONEHANDY_SITE_URL || process.env.NEXT_PUBLIC_SITE_URL || 'https://onehandy-v1.srv1691893.hstgr.cloud').replace(/\/$/, '');
  const ownerWhatsAppNumber = normalizeThaiPhone(process.env.ONEHANDY_PUBLIC_WHATSAPP_NUMBER || process.env.NEXT_PUBLIC_ONEHANDY_WHATSAPP_NUMBER || '66929894495');
  const customerPhone = normalizeThaiPhone(body.data?.phone);
  const customerReply = `Hi ${compact(body.data?.customerName, 'there')}, this is OneHandy Chiang Mai. We received your ${compact(body.data?.serviceName, 'home service')} request and are checking technician availability, timing, and quote. We will confirm the next step with you shortly.`;
  const replyUrl = customerPhone ? `https://wa.me/${customerPhone}?text=${encodeURIComponent(customerReply)}` : `https://wa.me/${ownerWhatsAppNumber}`;
  const adminUrl = `${siteUrl}/admin/requests/${encodeURIComponent(objectId)}`;

  const hermesPayload = {
    eventType,
    objectType,
    objectId,
    occurredAt: body.occurredAt || new Date().toISOString(),
    data: {
      serviceName: compact(body.data?.serviceName),
      status: compact(body.data?.status, 'new'),
      preferredDate: compact(body.data?.preferredDate),
      timeWindow: compact(body.data?.timeWindow),
      propertyType: compact(body.data?.propertyType),
      area: compact(body.data?.area),
      customerName: compact(body.data?.customerName),
      phone: compact(body.data?.phone),
      email: compact(body.data?.email),
      notes: compact(body.data?.notes),
      adminUrl,
      replyUrl,
    },
  };

  const hermesUrl = process.env.ONEHANDY_HERMES_WEBHOOK_URL || 'http://172.16.2.1:8644/webhooks/onehandy-draft';
  const hermesSecret = process.env.ONEHANDY_HERMES_WEBHOOK_SECRET || '';

  if (!hermesSecret) {
    hermesStatus = 503;
    hermesBody = 'ONEHANDY_HERMES_WEBHOOK_SECRET is not configured.';
  } else {
    const hermesRequestBody = JSON.stringify(hermesPayload);
    const hermesSignature = `sha256=${hmac(hermesRequestBody, hermesSecret)}`;
    const response = await fetch(hermesUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-GitHub-Event': eventType,
        'X-GitHub-Delivery': `${eventType}:${objectId}:${Date.now()}`,
        'X-Hub-Signature-256': hermesSignature,
      },
      body: hermesRequestBody,
    });

    hermesStatus = response.status;
    hermesBody = (await response.text()).slice(0, 1000);
    hermesDelivered = response.ok;
  }
}

return [{
  json: {
    statusCode: hermesStatus && hermesStatus >= 400 ? 502 : 200,
    responseBody: {
      ok: !(hermesStatus && hermesStatus >= 400),
      eventType,
      objectType,
      objectId,
      hermesDelivered,
      hermesStatus,
      hermesBody,
      receivedAt: new Date().toISOString(),
    },
  },
}];
